import type { Env } from "../config/env.js";
import {
	type OAuthAppCredentials,
	githubCredentials,
	googleCredentials,
} from "../config/integrations-env.js";
import type { UpstreamProfile } from "./account-linking.js";
import { createGithubUpstream } from "./upstream-github.js";
import { createGoogleUpstream } from "./upstream-google.js";
import type { UpstreamProvider } from "./user-model.js";

/** Per-sign-in secrets, generated by us and kept server-side until the callback. */
export interface UpstreamChecks {
	readonly state: string;
	readonly codeVerifier: string;
	/** OIDC providers only (Google): bound into the ID token. */
	readonly nonce: string;
}

/** One external sign-in provider, hiding the OAuth library behind it. */
export interface UpstreamClient {
	readonly provider: UpstreamProvider;
	authorizationUrl(checks: UpstreamChecks): Promise<URL>;
	/**
	 * Validates the callback query (state, code; ID token and nonce for
	 * Google), redeems the code and returns the person's provider profile.
	 */
	fetchProfile(
		callbackQuery: URLSearchParams,
		checks: UpstreamChecks,
	): Promise<UpstreamProfile>;
}

export type Upstreams = ReadonlyMap<UpstreamProvider, UpstreamClient>;

export const UPSTREAM_LABELS: Readonly<Record<UpstreamProvider, string>> = {
	google: "Google",
	github: "GitHub",
};

/** Fixed callback path registered with Google and GitHub. */
export function upstreamCallbackPath(provider: UpstreamProvider): string {
	return `/oauth/${provider}/callback`;
}

/**
 * Only providers with credentials are enabled; their callbacks are on
 * `issuer`, the tenant's own host (each tenant registers its own OAuth apps).
 */
export function createUpstreamsFrom(
	issuer: string,
	credentials: {
		readonly google?: OAuthAppCredentials;
		readonly github?: OAuthAppCredentials;
	},
): Upstreams {
	const upstreams = new Map<UpstreamProvider, UpstreamClient>();
	const callback = (provider: UpstreamProvider): string =>
		`${issuer}${upstreamCallbackPath(provider)}`;
	if (credentials.google) {
		upstreams.set(
			"google",
			createGoogleUpstream(credentials.google, callback("google")),
		);
	}
	if (credentials.github) {
		upstreams.set(
			"github",
			createGithubUpstream(credentials.github, callback("github")),
		);
	}
	return upstreams;
}

/** The primary tenant's providers, from the environment. */
export function createUpstreams(env: Env, issuer: string): Upstreams {
	return createUpstreamsFrom(issuer, {
		google: googleCredentials(env),
		github: githubCredentials(env),
	});
}
